target.expr:
max by (container, image, version) (
  label_replace(
    kube_pod_container_info{
      pod=~"w4-php-fpm.*",
      namespace="adm-it-pub-w4",
      container="w4-php-fpm"
    }
    unless on (namespace, container, image)
    kube_pod_container_info{
      pod=~"w4-php-fpm.*",
      namespace="adm-it-pub-w4",
      container="w4-php-fpm"
    } offset 5m,
    "version",
    "$1",
    "image",
    "^.*:([^@]+)(?:@sha256:.*)?$"
  )
)
